INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:vscode:config-model-v1','project_doc','seed://vscode/config-model','VS Code and Copilot command surface configuration model','Snapshot date: 2026-07-15. Canonical configuration paths: %APPDATA%/Code/User/settings.json, mcp.json, globalStorage; workspace .vscode/. Registration is additive, idempotent, and must preserve user-owned keys, hooks, rules, and MCP servers. Source: docs/UNIVERSAL_COMMAND_MATRIX.md and docs/SIMPLICIO_COMMAND_SURFACE.md.','docs/UNIVERSAL_COMMAND_MATRIX.md and docs/SIMPLICIO_COMMAND_SURFACE.md','b55705a6f2b5607c92ebd2067ce5be65ca4c92736605b4a7e9f1a4d6555b8ce2','vscode,config,mcp,rules',2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:vscode:integration-points-v1','project_doc','seed://vscode/integration','VS Code and Copilot command surface Simplicio integration points','Snapshot date: 2026-07-15. T2 MCP plus rules; native VS Code MCP uses servers entries with type stdio. Simplicio execution remains the governed control plane; provider surfaces are compatibility inputs, not alternate mutation paths. Source: docs/UNIVERSAL_COMMAND_MATRIX.md and docs/SIMPLICIO_COMMAND_SURFACE.md.','docs/UNIVERSAL_COMMAND_MATRIX.md and docs/SIMPLICIO_COMMAND_SURFACE.md','ebb8696695a0b34da1545093e5f6b9169ecd9acb09d25745787bb36e4f64b0ab','vscode,simplicio,integration,governance',2);
